-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Arbeitsschutz > Schutzausrüstung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb Schutzausrüstung wie antistatische Armbänder für Fachinformatiker bereitstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Schutz vor elektrostatischer Entladung bei Hardwarearbeiten"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben bei Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Schutzausrüstung in einem IT-Betrieb elektrische Unfälle verhindern?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. isolierende Handschuhe schützen bei Arbeiten an Geräten"}, {"text": "Nein", "correct": false, "because": "Prävention ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Schutzausrüstung für Fachinformatiker nur bei Hardwarewartung relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bei anderen Tätigkeiten wie Serverinstallation nötig"}, {"text": "Ja", "correct": false, "because": "Nicht auf Hardwarewartung beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Fachinformatiker Schutzausrüstung wie Sicherheitsschuhe bei der Arbeit in Serverräumen tragen?', 2, '[{"text": "Ja", "correct": true, "because": "Schwere Geräte erfordern Schutz gemäß DGUV"}, {"text": "Nein", "correct": false, "because": "Sicherheitsschuhe können vorgeschrieben sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Bereitstellung von Schutzausrüstung in einem IT-Betrieb eine freiwillige Maßnahme?', 2, '[{"text": "Nein", "correct": true, "because": "ArbSchG und DGUV machen sie zur Pflicht bei Gefährdung"}, {"text": "Ja", "correct": false, "because": "Gesetzlich geregelt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schutzausrüstung ist für Fachinformatiker bei der Arbeit mit Hardware besonders wichtig?', 2, '[{"text": "Antistatische Armbänder", "correct": true, "because": "Schützt vor elektrostatischer Entladung"}, {"text": "Lärmschutz", "correct": false, "because": "Weniger relevant bei Hardware"}, {"text": "Feuerlöscher", "correct": false, "because": "Kein persönlicher Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Bereitstellung von Schutzausrüstung in einem IT-Betrieb?', 3, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "ArbSchG § 3 fordert Schutzmaßnahmen"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "HGB", "correct": false, "because": "Regelt Handel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzausrüstung könnte ein Fachinformatiker bei der Arbeit an Servern benötigen?', 3, '[{"text": "Sicherheitsschuhe", "correct": true, "because": "Schützt bei schweren Geräten"}, {"text": "Sonnenbrille", "correct": false, "because": "Nicht relevant"}, {"text": "Hörschutz", "correct": false, "because": "Lärm nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für die Bereitstellung von Schutzausrüstung in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "ArbSchG legt Verantwortung beim Arbeitgeber"}, {"text": "Die Fachinformatiker", "correct": false, "because": "Nicht deren Pflicht"}, {"text": "Die Berufsgenossenschaft", "correct": false, "because": "Überwacht, stellt nicht bereit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Schutzausrüstung für Fachinformatiker?', 3, '[{"text": "Verhinderung von Arbeitsunfällen", "correct": true, "because": "Schutz vor Gefährdungen"}, {"text": "Erhöhung der Kosten", "correct": false, "because": "Kein Ziel"}, {"text": "Verringerung der Produktivität", "correct": false, "because": "Produktivität bleibt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schutzausrüstung ist für Fachinformatiker in einem IT-Betrieb relevant?', 4, '[{"text": "Antistatische Armbänder", "correct": true, "because": "Schutz vor elektrostatischer Entladung"}, {"text": "Sicherheitsschuhe", "correct": true, "because": "Schutz bei schweren Geräten"}, {"text": "Sonnenbrille", "correct": false, "because": "Nicht relevant"}, {"text": "Isolierende Handschuhe", "correct": true, "because": "Schutz vor Strom"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Schutzausrüstung einem IT-Betrieb?', 3, '[{"text": "Reduzierung von Arbeitsunfällen", "correct": true, "because": "Schutz vor Gefahren"}, {"text": "Erfüllung gesetzlicher Vorgaben", "correct": true, "because": "ArbSchG wird eingehalten"}, {"text": "Höhere Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Sicherheit der Mitarbeiter", "correct": true, "because": "Primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können durch Schutzausrüstung in einem IT-Betrieb entstehen?', 4, '[{"text": "Kosten für Anschaffung", "correct": true, "because": "Ausrüstung muss gekauft werden"}, {"text": "Einschränkung der Bewegungsfreiheit", "correct": true, "because": "Z. B. Handschuhe können stören"}, {"text": "Geringere Produktivität", "correct": false, "because": "Produktivität bleibt oder steigt"}, {"text": "Verwaltungsaufwand", "correct": true, "because": "Bereitstellung und Kontrolle nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln die Schutzausrüstung in einem IT-Betrieb?', 3, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "Regelt Arbeitsschutz"}, {"text": "DGUV-Vorschriften", "correct": true, "because": "Berufsgenossenschaftliche Regeln"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "PSA-Benutzungsverordnung", "correct": true, "because": "Regelt Persönliche Schutzausrüstung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gefahren werden durch Schutzausrüstung in einem IT-Betrieb minimiert?', 3, '[{"text": "Elektrostatische Entladung", "correct": true, "because": "Antistatische Armbänder schützen"}, {"text": "Stromschläge", "correct": true, "because": "Isolierende Handschuhe helfen"}, {"text": "Lärmbelastung", "correct": false, "because": "Weniger relevant"}, {"text": "Verletzungen durch schwere Geräte", "correct": true, "because": "Sicherheitsschuhe schützen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Schutzausrüstung ist in einem IT-Betrieb gesetzlich vorgeschrieben. b) Schutzausrüstung ist nur für Büroarbeit relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gesetzlich ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Antistatische Armbänder schützen Fachinformatiker bei Hardwarearbeiten. b) Der Arbeitgeber muss Schutzausrüstung bereitstellen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Schutz und Bereitstellungspflicht"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schutzausrüstung reduziert Arbeitsunfälle in einem IT-Betrieb. b) Schutzausrüstung erhöht die Produktivität direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unfälle ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Sicherheitsschuhe sind bei Serverarbeiten eine sinnvolle Schutzausrüstung. b) Schutzausrüstung ist in einem IT-Betrieb freiwillig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheitsschuhe ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schutzausrüstung kann Kosten für einen IT-Betrieb verursachen. b) Schutzausrüstung ist nur für Hardwarearbeiten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

